---
import Layout from '@/layouts/Layout.astro'
import Intro from '@/components/landing/sections/Intro.astro'
import RecentPosts from '@/components/landing/sections/RecentPosts.astro'
import RecentTalks from '@/components/landing/sections/RecentTalks.astro'
import VimNavigation from '@/components/landing/VimNavigation.astro'
---

<Layout>
    <main>
        <Intro />
        <RecentPosts />
        <RecentTalks />
    </main>
    <div id="vim-navigation-container">
        <VimNavigation />
    </div>
</Layout>

<style is:global>
    #vim-navigation-container {
        position: fixed;
        top: 1lh;
        right: 2ch;
    }

    main {
        height: 100vh;
        scroll-snap-type: y proximity;
        display: flex;
        flex-direction: column;
        overflow-y: auto;
        overflow-x: hidden;
        scrollbar-width: thin;
        scrollbar-color: var(--foreground1) var(--background2);
    }

    section,
    header {
        scroll-snap-align: start;
        display: flex;
        flex-direction: column;
    }

    header {
        min-height: 100vh;
    }

    section .content {
        max-width: 80ch;
        width: round(calc(100% - 2ch), 1ch);
        row-gap: 2ch;
        column-gap: 1lh;
    }

    @media (max-width: 1000px) {
        section .content {
            flex-direction: column-reverse;
        }
    }
</style>

