        display: flex;
        flex-direction: column;
        overflow-y: auto;
        overflow-x: hidden;
        scrollbar-width: thin;
        scrollbar-color: var(--foreground1) var(--background2);
    }

    section,
    header {
        scroll-snap-align: start;
        display: flex;
        flex-direction: column;
        min-height: 100vh;
